import{_ as r,C as i,o as t,c as l,a2 as a,b as s,w as o,a as n,E as c,a3 as p}from"./chunks/framework.D7Ov6LBE.js";const S=JSON.parse('{"title":"03 — Adaptadores ERP","description":"","frontmatter":{},"headers":[],"relativePath":"docs-legados/03-adaptadores-erp.md","filePath":"docs-legados/03-adaptadores-erp.md","lastUpdated":1786474711000}'),g={name:"docs-legados/03-adaptadores-erp.md"};function m(u,e,P,A,f,h){const d=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="_03-—-adaptadores-erp" tabindex="-1">03 — Adaptadores ERP <a class="header-anchor" href="#_03-—-adaptadores-erp" aria-label="Permalink to &quot;03 — Adaptadores ERP&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documento original</p><p>Conteúdo integral preservado de <code>docs/03-arquitetura-de-adapters-erp.md</code>. Parte da wiki para manter a rastreabilidade com a documentação histórica do projeto.</p></div><h2 id="_3-1-o-problema-da-heterogeneidade-dos-erps-corporativos" tabindex="-1">3.1 O Problema da Heterogeneidade dos ERPs Corporativos <a class="header-anchor" href="#_3-1-o-problema-da-heterogeneidade-dos-erps-corporativos" aria-label="Permalink to &quot;3.1 O Problema da Heterogeneidade dos ERPs Corporativos&quot;">​</a></h2><p>No mercado corporativo brasileiro, não existe um consenso ou formato único universal de API compartilhado entre os grandes ERPs (SAP S/4HANA, TOTVS Protheus/RM, Senior, Linx, Sankhya, Omie).</p><p>Cada ERP possui seus próprios protocolos, regras de negócio e taxonomias:</p><ul><li><strong>SAP S/4HANA:</strong> Utiliza <strong>OData v4 (REST/JSON)</strong> ou conectores <strong>RFC / BAPI</strong> via SOAP/ABAP;</li><li><strong>TOTVS Protheus:</strong> Utiliza APIs REST customizadas em <strong>ADVPL/TL++</strong> ou SOAP Web Services em formato XML/JSON proprietário (<code>MATA410</code> para pedidos de venda);</li><li><strong>Senior ERP:</strong> Utiliza rotas <strong>REST / SOAP</strong> com autenticação via ticket / tokens de sessão;</li><li><strong>Linx / Sankhya:</strong> Utilizam endpoints REST com padrões XML/JSON legados e nomenclaturas de tabelas de banco (ex: <code>TGFCAB</code>, <code>TGFITE</code>).</li></ul><hr><h2 id="_3-2-o-padrao-adapter-via-microservico-middleware" tabindex="-1">3.2 O Padrão &quot;Adapter via Microserviço&quot; (Middleware) <a class="header-anchor" href="#_3-2-o-padrao-adapter-via-microservico-middleware" aria-label="Permalink to &quot;3.2 O Padrão &quot;Adapter via Microserviço&quot; (Middleware)&quot;">​</a></h2><p>Para evitar acoplar a lógica do aplicativo móvel aos detalhes específicos de cada ERP, a arquitetura do <strong>Ampla Vendas ERP</strong> implementa o padrão <strong>Adapter via Microserviço (Canonical Data Model)</strong>.</p>',9)),(t(),s(p,null,{default:o(()=>[c(d,{id:"mermaid-46",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20PWA%5B%22App%20Mobile%20%2F%20PWA%20(Ampla%20Vendas)%22%5D%20--%3E%7C1.%20Payload%20Can%C3%B4nico%20em%20JSON%7C%20Middleware%5B%22Middleware%20Integration%20Service%20(Node.js%20%2F%20Go)%22%5D%0A%20%20%20%20%0A%20%20%20%20subgraph%20Adapters%20%5B%22Camada%20de%20Adapters%20%2F%20Decodificadores%22%5D%0A%20%20%20%20%20%20%20%20Middleware%20--%3E%7C2a.%20SAP%20Adapter%7C%20SAPAdapter%5B%22SAP%20Adapter%20(Converte%20p%2F%20OData%2FBAPI)%22%5D%0A%20%20%20%20%20%20%20%20Middleware%20--%3E%7C2b.%20TOTVS%20Adapter%7C%20TOTVSAdapter%5B%22TOTVS%20Adapter%20(Converte%20p%2F%20ADVPL%20REST%20MATA410)%22%5D%0A%20%20%20%20%20%20%20%20Middleware%20--%3E%7C2c.%20Senior%20Adapter%7C%20SeniorAdapter%5B%22Senior%20Adapter%20(Converte%20p%2F%20SOAP%2FREST%20Senior)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20SAPAdapter%20--%3E%7C3a.%20HTTPS%20OData%7C%20SAP%5B%22SAP%20S%2F4HANA%20Cloud%22%5D%0A%20%20%20%20TOTVSAdapter%20--%3E%7C3b.%20HTTPS%20Rest%7C%20TOTVS%5B%22TOTVS%20Protheus%22%5D%0A%20%20%20%20SeniorAdapter%20--%3E%7C3c.%20HTTPS%20SOAP%7C%20Senior%5B%22Senior%20ERP%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-3-mapeamento-de-payload-canonico-vs-erps" tabindex="-1">3.3 Mapeamento de Payload Canônico vs ERPs <a class="header-anchor" href="#_3-3-mapeamento-de-payload-canonico-vs-erps" aria-label="Permalink to &quot;3.3 Mapeamento de Payload Canônico vs ERPs&quot;">​</a></h2><p>O aplicativo móvel envia sempre o <strong>Payload Canônico</strong>, simplificado e imutável. O <strong>Adapter do ERP</strong> traduz cada campo:</p><h3 id="tabela-de-de-para-de-atributos" tabindex="-1">Tabela de De-Para de Atributos <a class="header-anchor" href="#tabela-de-de-para-de-atributos" aria-label="Permalink to &quot;Tabela de De-Para de Atributos&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Atributo Canônico (PWA)</th><th style="text-align:left;">Descrição</th><th style="text-align:left;">SAP S/4HANA (API_SALES_ORDER)</th><th style="text-align:left;">TOTVS Protheus (MATA410)</th><th style="text-align:left;">Senior ERP (Gerais)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>codigoPedido</code></td><td style="text-align:left;">ID único da venda</td><td style="text-align:left;"><code>PurchaseOrderByCustomer</code></td><td style="text-align:left;"><code>C5_NUM</code> / <code>C5_XCODPED</code></td><td style="text-align:left;"><code>numPed</code></td></tr><tr><td style="text-align:left;"><code>dataCriacao</code></td><td style="text-align:left;">Data/hora de emissão</td><td style="text-align:left;"><code>SalesOrderDate</code></td><td style="text-align:left;"><code>C5_EMISSAO</code> (AAAAMMDD)</td><td style="text-align:left;"><code>datEmi</code></td></tr><tr><td style="text-align:left;"><code>clientCpfCnpj</code></td><td style="text-align:left;">Documento do Cliente</td><td style="text-align:left;"><code>SoldToParty</code> (via Business Partner)</td><td style="text-align:left;"><code>C5_CLIENTE</code> + <code>C5_LOJA</code></td><td style="text-align:left;"><code>codCil</code> / <code>cgccpf</code></td></tr><tr><td style="text-align:left;"><code>vendedorId</code></td><td style="text-align:left;">Matrícula do Vendedor</td><td style="text-align:left;"><code>Salesperson</code></td><td style="text-align:left;"><code>C5_VEND1</code></td><td style="text-align:left;"><code>codVen</code></td></tr><tr><td style="text-align:left;"><code>total</code></td><td style="text-align:left;">Valor total líquido</td><td style="text-align:left;"><code>TotalNetAmount</code></td><td style="text-align:left;"><code>C5_TOTAL</code></td><td style="text-align:left;"><code>vlrLqd</code></td></tr><tr><td style="text-align:left;"><code>formaPagamento</code></td><td style="text-align:left;">Meio de pagamento</td><td style="text-align:left;"><code>PaymentTerms</code></td><td style="text-align:left;"><code>C5_MENPAD</code> / <code>C5_CONDPAG</code></td><td style="text-align:left;"><code>codCpg</code></td></tr><tr><td style="text-align:left;"><code>itens[].sku</code></td><td style="text-align:left;">Código de barras / SKU</td><td style="text-align:left;"><code>Material</code></td><td style="text-align:left;"><code>C6_PRODUTO</code></td><td style="text-align:left;"><code>codPro</code></td></tr><tr><td style="text-align:left;"><code>itens[].quantidade</code></td><td style="text-align:left;">Qtd vendida</td><td style="text-align:left;"><code>RequestedQuantity</code></td><td style="text-align:left;"><code>C6_QTDVEN</code></td><td style="text-align:left;"><code>qtdPed</code></td></tr><tr><td style="text-align:left;"><code>itens[].precoUnitario</code></td><td style="text-align:left;">Preço unitário</td><td style="text-align:left;"><code>NetPriceAmount</code></td><td style="text-align:left;"><code>C6_PRCVEN</code></td><td style="text-align:left;"><code>preUni</code></td></tr></tbody></table><hr><h2 id="_3-4-padroes-de-resiliencia-dlq-backoff-e-idempotencia" tabindex="-1">3.4 Padrões de Resiliência: DLQ, Backoff e Idempotência <a class="header-anchor" href="#_3-4-padroes-de-resiliencia-dlq-backoff-e-idempotencia" aria-label="Permalink to &quot;3.4 Padrões de Resiliência: DLQ, Backoff e Idempotência&quot;">​</a></h2><h3 id="_1-idempotencia-por-chave-unica-codigopedido" tabindex="-1">1. Idempotência por Chave Única (<code>codigoPedido</code>) <a class="header-anchor" href="#_1-idempotencia-por-chave-unica-codigopedido" aria-label="Permalink to &quot;1. Idempotência por Chave Única (`codigoPedido`)&quot;">​</a></h3><p>Para evitar duplicidade de pedidos no ERP (ex: se o vendedor clicar duas vezes ou se a conexão cair durante a resposta HTTP), o ERP deve usar o <code>codigoPedido</code> como <strong>Chave de Idempotência</strong>. Se o Adapter receber um pedido com um <code>codigoPedido</code> já processado, ele retorna o status <code>200 OK</code> com o número já gerado no ERP, sem criar um segundo pedido.</p><h3 id="_2-exponential-backoff-retentativa-progressiva" tabindex="-1">2. Exponential Backoff (Retentativa Progressiva) <a class="header-anchor" href="#_2-exponential-backoff-retentativa-progressiva" aria-label="Permalink to &quot;2. Exponential Backoff (Retentativa Progressiva)&quot;">​</a></h3><p>Em caso de quedas temporárias na API do ERP (ex: manutenção noturna do Protheus ou SAP), o Middleware reagenda a tentativa de envio com tempo dobrado a cada falha (1s, 2s, 4s, 8s, 16s, ... até 5 tentativas).</p><h3 id="_3-dead-letter-queue-dlq" tabindex="-1">3. Dead Letter Queue (DLQ) <a class="header-anchor" href="#_3-dead-letter-queue-dlq" aria-label="Permalink to &quot;3. Dead Letter Queue (DLQ)&quot;">​</a></h3><p>Se após 5 tentativas o ERP continuar indisponível ou retornar um erro definitivo de validação (ex: <em>&quot;Cliente bloqueado no ERP por inadimplência&quot;</em>), o pedido é movido para a <strong>Fila de Exceções (DLQ)</strong>. O pedido fica destacado na <strong>Central de Sincronização (ErpSyncCenter)</strong> do aplicativo para correção manual pelo supervisor.</p>',13))])}const v=r(g,[["render",m]]);export{S as __pageData,v as default};
